using System.Net;
using System.Net.NetworkInformation;
using System.Net.Sockets;
namespace HomeLibrary;
public static class SetupStatus {
 public const string Version="2.0.59-preview";
 public static object Read(Settings settings,string data,Store store,Identity identity){
  var state=store.Read().State;var files=Directory.Exists(Path.Combine(data,"backups"))?Directory.GetFiles(Path.Combine(data,"backups"),"*.hlbackup"):[];
  var local=NetworkInterface.GetAllNetworkInterfaces().Where(n=>n.OperationalStatus==OperationalStatus.Up&&n.NetworkInterfaceType!=NetworkInterfaceType.Loopback).SelectMany(n=>n.GetIPProperties().UnicastAddresses).Where(a=>a.Address.AddressFamily==AddressFamily.InterNetwork&&!IPAddress.IsLoopback(a.Address)).Select(a=>$"https://{a.Address}:{settings.PhonePort}").Distinct().ToArray();
  return new{recoveryReviewRequired=settings.RecoveryReviewRequired,recoveryRehearsal=settings.RecoveryRehearsal,version=Version,platform=OperatingSystem.IsWindows()?"Windows":DesktopSession.IsFlatpak?"Linux Flatpak":"Linux / Raspberry Pi",dataDirectory=data,books=state.Books.Count(b=>!b.Archived),borrowers=state.Borrowers.Count(b=>!b.Archived),backupCount=files.Length,latestBackup=files.OrderByDescending(File.GetLastWriteTimeUtc).Select(f=>File.GetLastWriteTimeUtc(f).ToString("u")).FirstOrDefault(),pairedPhones=identity.Devices().Count(d=>!d.Revoked),remoteAddress=settings.RemoteAddress,publicOrigin=settings.PublicCatalogOrigin,localAddresses=local,phonePort=settings.PhonePort,adminPort=settings.AdminPort,catalogPort=settings.CatalogPort,discoveryPort=settings.DiscoveryPort,
   remoteInstructions=OperatingSystem.IsWindows()?"Open Carribrary → Connection setup from the Windows Start menu (or the tray menu). Enter a hostname and optionally your DuckDNS token. The wizard saves settings, updates DNS and restarts the service. Use its public-sharing button for browser HTTPS.":"Open Settings & Tools → System & Advanced → Public sharing setup on this server. The GUI installs its own verified Caddy and optionally updates DuckDNS. Router TCP 80→8080 and 443→8443 must target this server. The paired-phone port stays separate. Flatpak must remain running; the Pi service starts at boot.",
   updateInstructions=OperatingSystem.IsWindows()?"Run the new Windows installer over this installation. It stops the service, verifies program files, saves a complete private recovery point, preserves settings/data, then checks startup and the catalog. Use Start → Carribrary → Update and recovery even if the library page cannot open. Program recovery supports compatible 2.0.59 format-7 programs. Complete Backup Recovery in the Start menu verifies, rehearses and restores saved complete archives; it is separate from program rollback. The new permanent-copy identity format cannot be opened by 2.0.30 or earlier; cross-format rollback is not offered.":DesktopSession.IsFlatpak?"Quit Carribrary, then open the new Flatpak bundle in your software manager and choose Update. Reopen Carribrary afterward.":"Install the new ARM64 DEB using the package manager. The existing service is stopped and restarted; its data stays in /var/lib/home-library."};
 }
 public static async Task<object> Dns(Settings settings,CancellationToken stop){if(!Uri.TryCreate(settings.RemoteAddress,UriKind.Absolute,out var uri))throw new LibraryError("Save the remote hostname in Connection setup first.");try{using var timeout=CancellationTokenSource.CreateLinkedTokenSource(stop);timeout.CancelAfter(TimeSpan.FromSeconds(5));var addresses=await System.Net.Dns.GetHostAddressesAsync(uri.Host,timeout.Token);return new{message=addresses.Length==0?"The saved hostname has no DNS addresses.":$"{uri.Host} resolves to {string.Join(", ",addresses.Select(a=>a.ToString()))}. DNS works; test the actual connection on cellular to verify router forwarding."};}catch(Exception e)when(e is SocketException or OperationCanceledException){throw new LibraryError("The saved hostname could not be resolved. Check DuckDNS updates and the server's internet connection.");}}
}
